import pytest
from candidate import change_base

def test_change_base_normalcase_expected_behavior():
    assert change_base(8, 3) == "22"
    assert change_base(8, 2) == "1000"
    assert change_base(7, 2) == "111"

def test_change_base_boundary_base_minimum():
    assert change_base(10, 2) == "1010"
    assert change_base(1, 2) == "1"

def test_change_base_boundary_base_maximum_under_ten():
    assert change_base(10, 9) == "11"
    assert change_base(99, 9) == "121"

def test_change_base_zero_input():
    assert change_base(0, 2) == ""

def test_change_base_none_input_x():
    with pytest.raises(TypeError):
        change_base(None, 2)

def test_change_base_none_input_base():
    with pytest.raises(TypeError):
        change_base(10, None)

def test_change_base_type_error_x():
    with pytest.raises(TypeError):
        change_base("10", 2)

def test_change_base_type_error_base():
    with pytest.raises(TypeError):
        change_base(10, "2")

def test_change_base_negative_x():
    assert change_base(-5, 2) == ""

def test_change_base_negative_base():
    assert change_base(5, -2) == "-1"

def test_change_base_large_number():
    large_number = 2 ** 100
    assert change_base(large_number, 2) == "1" + "0" * 100
    assert change_base(large_number, 9) == str(large_number)  # base 9 returns decimal representation

def test_change_base_non_integer_base_below_ten():
    assert change_base(27, 4) == "123"

def test_change_base_non_integer_x_with_integer_base():
    with pytest.raises(TypeError):
        change_base(10.5, 3)

def test_change_base_negative_base_and_negative_x():
    assert change_base(-10, -2) == ""

def test_change_base_base_greater_than_nine():
    assert change_base(15, 10) == "15"
    assert change_base(15, 11) == "14"
    assert change_base(15, 12) == "13"  # 15 in base 12 is 13

def test_change_base_multiple_digit_conversion():
    assert change_base(255, 2) == "11111111"
    assert change_base(255, 3) == "10022"
    assert change_base(255, 5) == "1440"

def test_change_base_boundary_small_number():
    assert change_base(1, 9) == "1"
    assert change_base(8, 9) == "8"

def test_change_base_boundary_large_base():
    assert change_base(1000, 9) == "1334"

def test_change_base_edge_zero_base():
    with pytest.raises(ZeroDivisionError):
        change_base(10, 0)
